/**
 * universeDatabase.ts
 * ═══════════════════════════════════════════════════════════════════════════
 * EXPANDED UNIVERSE DATABASE — 1000 structured universes (500 realistic + 500 fantasy)
 * ═══════════════════════════════════════════════════════════════════════════
 *
 * Each universe has structured metadata for intelligent filtering.
 * "Surprise Me" uses this metadata to avoid irrelevant picks.
 *
 * Used by:
 *   - constants.ts (getRandomUniverse)
 *   - InputForm.tsx (universe selector)
 * ═══════════════════════════════════════════════════════════════════════════
 */

export interface UniverseEntry {
    id: string;
    name: string;
    nameAr: string;
    category: string;
    styleFamily: 'realistic' | 'fantasy';
    tone: string;
    /** Which business niches this universe fits well */
    businessFit: string[];
    /** Which offer types benefit from this universe */
    offerFit: string[];
    /** Aspiration/positioning signals this universe communicates */
    aspirationSignals: string[];
    /** Credibility signals this universe communicates */
    credibilitySignals: string[];
    /** Business contexts where this universe should NOT be used */
    forbiddenFits: string[];
    /** Key visual elements that define this universe */
    visualMotifs: string[];
    /** Whether the environment has enough clear space for text-dense layouts */
    safeForTextDensity: boolean;
}

