// ═══════════════════════════════════════════════════════════════════════════
// FILTERING / RECOMMENDATION
// ═══════════════════════════════════════════════════════════════════════════

export const ALL_UNIVERSES = [...REALISTIC_UNIVERSES, ...FANTASY_UNIVERSES];

/**
 * Filter universes by relevance to the user's niche and offer.
 * Returns scored and sorted universes (best fit first).
 */
export function filterUniverses(
    styleFamily: 'realistic' | 'fantasy' | 'any',
    context: {
        niche?: string;
        offerType?: string;
        targetAudience?: string;
        productName?: string;
    }
): UniverseEntry[] {
    const pool = styleFamily === 'any'
        ? ALL_UNIVERSES
        : styleFamily === 'realistic'
            ? REALISTIC_UNIVERSES
            : FANTASY_UNIVERSES;

    if (!context.niche && !context.offerType) return pool;

    const scored = pool.map(u => {
        let score = 0;
        const ctx = `${context.niche || ''} ${context.offerType || ''} ${context.targetAudience || ''} ${context.productName || ''}`.toLowerCase();

        // Business fit bonus
        for (const fit of u.businessFit) {
            if (ctx.includes(fit.toLowerCase())) score += 3;
        }
        // Offer fit bonus
        if (context.offerType && u.offerFit.includes(context.offerType)) score += 2;
        // Forbidden penalty
        for (const forbidden of u.forbiddenFits) {
            if (ctx.includes(forbidden.toLowerCase())) score -= 5;
        }
        return { u, score };
    });

    scored.sort((a, b) => b.score - a.score);
    return scored.map(s => s.u);
}

/**
 * Get a smart random universe — biased toward relevance.
 * Picks from top-20 relevant universes for variety.
 */
export function getSmartRandomUniverse(
    styleFamily: 'realistic' | 'fantasy',
    context: {
        niche?: string;
        offerType?: string;
        targetAudience?: string;
        productName?: string;
    }
): UniverseEntry {
    const filtered = filterUniverses(styleFamily, context);
    // Pick from top 20 for variety (or all if fewer)
    const topPool = filtered.slice(0, Math.min(20, filtered.length));
    return topPool[Math.floor(Math.random() * topPool.length)] || filtered[0];
}
